        return 'Error'
    parts: list[str] | None = expression.split()
    if len(parts) != 3:
        return 'Error'

    try:
        n1: float | None = float(parts[0])
        op: str = parts[1]
        n2: float | None = float(parts[2])
    except ValueError:
        return 'Error'

    if n1 is None or n2 is None:
        return 'Error'

    return simple_calculator(n1, op, n2)

