def run_length_encode(s: str | None) -> str:
    """Encodes a string using run-length encoding."""
    if s is None or not s:
        return ""

    encoded_string: list[str] = []
    i: int | None = 0
    n: int = len(s)

    while i is not None and i < n:
        count: int = 1
        current_char: str | None = s[i]
        j: int | None = i + 1

        while j is not None and j < n and s[j] == current_char:
            count += 1
            j += 1

        if current_char is not None:
            encoded_string.append(f"{current_char}{count}")

        i = j if j is not None else None 

    return "".join(encoded_string)

